// 単語カード（フラッシュカード）のデータ。
// roadmap / mindset と同じく、まずは新テーブルを作らずハードコード定数で持つ。
// 元データは各問題の解説キーワード(terms)＋G検定チートシート頻出語(6ソース突き合わせ)を、
// explanation-clarity 基準で「やさしく一言(gist)＋たとえ(eg)＋正確な定義(precise)」の3層に整えたもの。
// 難しい語ほど一見で像が結ぶよう、カード裏は gist→eg を先頭に大きく出し、precise は畳んで見せる。

export interface FlashCard {
  cat: string;      // シラバス大分類
  term: string;     // 用語（カード表）
  gist: string;     // やさしく一言：前提知識ゼロで読める1文（カード裏の主役）
  eg: string;       // たとえると：日常の比喩（抽象語を像にする）
  use?: string;     // 使いどころ：具体的にどんな場面でどう役立つか（1〜2文）
  precise: string;  // 正確な定義：厳密版（既定では畳む）
  src: string;      // 出典（「第N問 · …」or「分類 · …」）
}

export interface FlashDeck {
  key: string;   // examGroupKey に対応（将来の区分横断用）
  name: string;  // 表示名
  cards: FlashCard[];
}

// 分類の表示順（カード表のラベル色にも使う）。
export const FLASHCARD_CATEGORY_ORDER: string[] = ["動向","AIの難問","機械学習","強化学習","評価","DL概要","DL手法","応用","生成AI","数理統計","法律倫理"];

// 分類 → アクセント色（「静かな計器」= 低彩度の青系に寄せる）。
export const FLASHCARD_CATEGORY_COLOR: Record<string, string> = {
  "動向": "#8fa8c9", "AIの難問": "#9a8fc9", "機械学習": "#60a5fa", "強化学習": "#6aa0d8",
  "評価": "#7c9fe0", "DL概要": "#7aa2d8", "DL手法": "#6fa0c8", "応用": "#6ea0c8",
  "生成AI": "#60a5fa", "数理統計": "#8f9fc9", "法律倫理": "#8fa8b9",
  // Docker (DCA)
  "基礎": "#6ea0c8", "イメージ": "#60a5fa", "Swarm": "#7c9fe0", "ネットワーク": "#6aa0d8",
  "ストレージ": "#8f9fc9", "設定": "#7aa2d8", "セキュリティ": "#9a8fc9", "CLI弁別": "#6fa0c8",
  // GCP PCDE (Cloud DevOps)
  "SRE": "#60a5fa", "CI/CD": "#7c9fe0", "ブートストラップ": "#6ea0c8", "オブザーバビリティ": "#6aa0d8", "最適化": "#8f9fc9",
};

export function categoryColor(cat: string): string {
  return FLASHCARD_CATEGORY_COLOR[cat] ?? "#8892a4";
}

